ImcEnvelopedData ::= SEQUENCE {
    version Version,
    recipientInfos imcRecipientInfos,
    encryptedContentInfo EncryptedContentInfo
}
imcRecipientInfos ::= SET OF imcRecipientInfo

ImcRecipientInfo ::= SEQUENCE {
    version Version,
    rid CertificateId,
    keyEncryptionAlgorithm KeyEncryptionAlgorithmIdentifier,
    encryptedKey OCTET STRING
}

Parameters ::= CHOICE {
    ecParameters ECParameters,
    namedCurve ObjectIdentifier,
    implicitlyCA NULL }

SubjectPublicKeyInfo ::= SEQUENCE {
    algorithm AlgorithmIdentifier{{ECPKAlgorithms}},
    subjectPublicKey SM2PublicKey
}

AlgorithmIdentifier ::= SEQUENCE {
    algorithm OBJECT IDENTIFIER,
    parameters ANY DEFINED BY algorithm OPTIONAL
}

ECPrivateKey{CURVES:IOSet} ::= SEQUENCE {
    version INTEGER {ecPrivkeyVer1(1)}(ecPrivkeyVer1),
    privateKey SM2PrivateKey,
    parameters[0] Parameters{{IOSet}} OPTIONAL,
    publicKey[1] SM2PublicKey
}

CARequest ::= SEQUENCE {
    ksRequest           KSRequest,
    signatureAlgorithm  AlgorithmIdentifier,
    signatureValue      OCTET STRING
}

KSRequest ::= SEQUENCE {
    version      Version DEFAULT v2,
    caName       EntName,
    requestList  SEQUENCE OF Request,
    requestTime  GeneralizedTime,
    taskNo       INTEGER
}
Version ::= INTEGER {v2(1)}
EntName ::= SEQUENCE {
    hashAlgorithm  AlgorithmIdentifier,
    entName        GeneralName,
    entPubKeyHash  OCTET STRING,
    serialNumber   CertificateSerialNumber
}
CertificateSerialNumber ::= INTEGER
Request ::= CHOICE{
    applyKeyReq    [0] IMPLICT ApplyKeyReq,
    restoreKeyReq  [1] IMPLICT RestoreKeyReq,
    revokeKeyReq   [2] IMPLICT RevokeKeyReq
}

KMRespond ::= SEQUENCE {
    ksRespond           KSRespond,
    signatureAlgorithm  AlgorithmIdentifier,
    signatureValue      OCTET STRING
}

KSRespond ::= SEQUENCE {
    version      Version DEFAULT v2,
    KMName       EntName,
    respondList  SEQUENCE OF Respond,
    respondTime  GeneralizedTime,
    taskNo       INTEGER
}
Respond ::= CHOICE{
    applykeyRespond    [0] IMPLICT RetKeyRespond,
    restorekeyRespond  [1] IMPLICT RetKeyRespond,
    revokekeyRespond   [2] IMPLICT RevokeKeyRespond,
    errorPkgRespond    [3] IMPLICT ErrorPkgRespond
}

retKeyRespond ::= SEQUENCE {
    userCertNo  CertificateSerialNumber,
    retPubKey   SubjectPublicKeyInfo,
    retPriKey   SM2EnvelopedKey
}

ErrorPkgRespond ::= SEQUENCE {
    errNo    INTEGER,
    errDesc  [0] PKIFreeText OPTIONAL
}

AttributeValueAssertion ::= SEQUENCE {
    attributeType       AttributeType,
    attributeValue      AttributeValue
}
AttributeType ::= LDAPString
AttributeValue ::= OCTET STRING

BindRequest ::= [APPLICATION 0] SEQUENCE {
    version         INTEGER (1 .. 127),
    name            LDAPDN,
    authentication  AuthenticationChoice
}
AuthenticationChoice ::= CHOICE {
    simple          [0] OCTET STRING, --1 and 2 reserved
    sasl            [3] SaslCredentials
}
SaslCredentials ::= SEQUENCE {
    mechanism       LDAPString,
    credentials     OCTET STRING OPTIONAL
}

BindResponse ::= [APPLICATION 1] SEQUENCE {
    ldapResult      COMPONENTS OF LDAPResult,
    serverSaslCreds  [7] OCTET STRING OPTIONAL
}

SearchRequest ::= [APPLICATION 3] SEQUENCE {
    baseObject      LDAPDN,
    scope           ENUMERATED {
        baseObject                  (0),
        singleLevel                 (1),
        wholeSubtree                (2)
    },
    derefAliases    ENUMERATED {
        neverDerefAliases           (0),
        derefInSearching            (1),
        derefFindingBaseObject      (2),
        derefAlways                 (3)
    },
    sizeLimit       INTEGER (0 .. maxInt),
    timeLimit       INTEGER (0 .. maxInt),
    attrsOnly       BOOLEAN,
    filter          Filter,
    attributes      SEQUENCE OF AttributeType
}
Filter ::= CHOICE {
    and             [0] SET OF Filter,
    or              [1] SET OF Filter,
    not             [2] Filter,
    equalityMatch   [3] AttributeValueAssertion,
    substrings      [4] SubstringFilter,
    greaterOrEqual  [5] AttributeValueAssertion,
    lessOrEqual     [6] AttributeValueAssertion,
    present        [7] AttributeType,
    approxMatch     [8] AttributeValueAssertion,
    extensibleMatch [9] MatchingRuleAssertion
}
SubstringFilter ::= SEQUENCE {
    type            AttributeType, --at least one must be present
    substrings      SEQUENCE OF CHOICE {
        initial         [0] LDAPString,
        any             [1] LDAPString,
        final           [2] LDAPString
    }
}
MatchingRuleAssertion ::= SEQUENCE {
    matchingRule    [1] MatchingRuleId OPTIONAL,
    type            [2] AttributeDescription OPTIONAL,
    matchValue      [3] AssertionValue,
    dnAttributes    [4] BOOLEAN DEFAULT FALSE
}

SearchResultEntry ::= [APPLICATION 4] SEQUENCE {
    objectName      LDAPDN,
    attributes      PartialAttributeList
}
